formulas.expression:
VALUE(
LEFT(
  RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:")),
  FIND("</b>", RIGHT({!OutputFormatFetched}, LEN({!OutputFormatFetched}) - FIND("BIOS battery:", {!OutputFormatFetched}) - LEN("BIOS battery:"))) - 1
)
)
